<script setup lang="ts">
import { onMounted, ref } from 'vue'; import { api,unwrap } from '../api/client'; import type { PageResponse } from '../types'; import { useListQuery } from '../composables/useListQuery'; import MBPageHeader from '../components/MBPageHeader.vue'; import MBStatusTag from '../components/MBStatusTag.vue'
const {query,syncQuery}=useListQuery({page:1,size:20,status:'',keyword:''}); const result=ref<PageResponse<any>>({page:1,size:20,total:0,records:[]}); const loading=ref(false); async function load(){loading.value=true;try{await syncQuery();result.value=unwrap(await api.get('/tenant/usage-events',{params:query}))}finally{loading.value=false}} onMounted(load)
</script>
<template><MBPageHeader title="用量记录" subtitle="按租户隔离的原始用量事件；不会在前端推断计费结果。"/><section class="mb-card table-card"><div class="filter-bar"><el-input v-model="query.keyword" clearable placeholder="事件、来源或模型" @keyup.enter="query.page=1;load()"/><el-select v-model="query.status" clearable placeholder="全部状态"><el-option v-for="s in ['RECEIVED','PROCESSED','RETRYABLE_FAILED','FINAL_FAILED']" :key="s" :value="s" :label="s"/></el-select><el-button type="primary" @click="query.page=1;load()">查询</el-button></div><el-table v-loading="loading" :data="result.records"><el-table-column prop="eventId" label="事件ID" min-width="220" show-overflow-tooltip/><el-table-column prop="sourceId" label="来源" width="140"/><el-table-column prop="subscriptionId" label="订阅" width="90"/><el-table-column prop="modelCode" label="模型" min-width="150"/><el-table-column prop="meterCode" label="计量项" min-width="140"/><el-table-column prop="quantity" label="用量" width="120"/><el-table-column label="状态" width="130"><template #default="{row}"><MBStatusTag :status="row.status"/></template></el-table-column><el-table-column prop="occurredAt" label="发生时间" min-width="190"/><el-table-column prop="lastError" label="错误" min-width="220" show-overflow-tooltip/></el-table><div class="pagination"><el-pagination v-model:current-page="query.page" v-model:page-size="query.size" :page-sizes="[10,20,50,100]" :total="result.total" layout="total, sizes, prev, pager, next" @current-change="load" @size-change="query.page=1;load()"/></div></section></template>
